def merge(items):
    sorted_items = sorted(items)
    out = []
    for start, end in sorted_items:
        if start > end:
            raise ValueError("start must be <= end")
        if start == end:
            continue
        if out and start <= out[-1][1]:
            out[-1] = (out[-1][0], max(out[-1][1], end))
        else:
            out.append((start, end))
    return out
